// ═══ MEGA-UNIVERSE BUILD ═══
// Assembles a large drug universe: canonical molecule library (name-normalized
// to merge salt variants) generated by the mega-universe swarm + existing
// curated data, then assigns molecules to a 40-company roster with realistic
// overlap. Emits companies.js / indications.js / pipeline.js.
//
//   node scripts/build-universe.mjs <mega-universe-workflow-output.json>
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");
const DATA = path.join(ROOT, "src", "lib", "data");

const VALID_COUNTRIES = new Set(["US","CA","BR","MX","EU","UK","DE","FR","IT","ES","CH","RU","JP","CN","KR","AU","IN","IL","SA","TR"]);
const VALID_TA = new Set(["oncology","cardiovascular","cns","metabolic","inflammation","respiratory","gi","hematology","urology"]);
const ALL_TA = [...VALID_TA];

const outFile = process.argv[2];
if (!outFile) { console.error("usage: node build-universe.mjs <workflow-output>"); process.exit(1); }

// ── Deterministic RNG (reproducible builds) ──
function mulberry32(seed) { return function () { seed |= 0; seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
const rng = mulberry32(20260529);

// ── Name normalization: strip salt/hydrate suffixes so variants merge ──
const SALTS = /\b(hcl|hydrochloride|sodium|potassium|calcium|magnesium|sulfate|sulphate|besylate|mesylate|maleate|citrate|bisulfate|tartrate|succinate|acetate|fumarate|hemifumarate|bromide|chloride|phosphate|nitrate|tromethamine|valerate|propionate|dipropionate|furoate|xinafoate|hyclate|monohydrate|dihydrate|trihydrate|disodium|dimaleate|hydrobromide|pamoate|embonate|axetil)\b/gi;
function canon(name) {
  return String(name).toLowerCase().replace(/\(.*?\)/g, "").replace(SALTS, "").replace(/[^a-z0-9]+/g, " ").trim();
}
function normInd(s) { return String(s).toLowerCase().replace(/\s+/g, " ").trim(); }

// ── Load existing curated data ──
const companiesMod = await import(pathToFileURL(path.join(DATA, "companies.js")).href);
const indicationsMod = await import(pathToFileURL(path.join(DATA, "indications.js")).href);
const pipelineMod = await import(pathToFileURL(path.join(DATA, "pipeline.js")).href);
const existingCompanies = companiesMod.COMPANIES;
const competitive = structuredClone(pipelineMod.COMPETITIVE_PIPELINE);
const unmet = structuredClone(pipelineMod.UNMET_NEED);

// ── Canonical molecule library: canonKey -> { display, class, atc, ta, indications: Map } ──
const lib = new Map();
function ingestMolecule(mol, indications) {
  const ta = VALID_TA.has(mol.ta) ? mol.ta : "inflammation";
  const key = canon(mol.name);
  if (!key) return;
  let e = lib.get(key);
  if (!e) { e = { display: mol.name, class: mol.class || "—", atc: mol.atc || "—", ta, originalIndication: mol.originalIndication || "", indCount: 0, indications: new Map() }; lib.set(key, e); }
  if (mol.class && mol.class.length > (e.class === "—" ? 0 : e.class.length)) e.class = mol.class;
  if (mol.atc && mol.atc !== "—" && e.atc === "—") e.atc = mol.atc;
  if (mol.originalIndication && !e.originalIndication) e.originalIndication = mol.originalIndication;
  for (const ind of indications || []) {
    const countries = (ind.countries || []).filter(c => VALID_COUNTRIES.has(c));
    const ik = normInd(ind.indication);
    if (!ik) continue;
    const prev = e.indications.get(ik);
    const clean = { indication: ind.indication, countries, evidence: ind.evidence || "Phase II", patients: ind.patients || "N/A" };
    if (!prev || countries.length > prev.countries.length) e.indications.set(ik, clean);
  }
}

for (const c of existingCompanies) for (const mol of c.molecules) ingestMolecule(mol, indicationsMod.generateIndicationData(mol));

const PS_FORCE = new Set();
for (const c of existingCompanies) if (c.id === "pharmascience") for (const mol of c.molecules) PS_FORCE.add(canon(mol.name));

const raw = JSON.parse(fs.readFileSync(outFile, "utf8"));
const R = raw.result || raw;
for (const sl of R.slices || []) {
  const d = sl.data || sl;
  for (const mol of d.molecules || []) ingestMolecule(mol, mol.indications);
  for (const [ind, rivals] of Object.entries(d.competitive || {})) if (!competitive[ind] && Array.isArray(rivals) && rivals.length) competitive[ind] = rivals;
  for (const [ind, info] of Object.entries(d.unmet || {})) if (!unmet[ind] && info && typeof info.score === "number") unmet[ind] = info;
}

// ── Finalize molecule records ──
const molecules = [...lib.values()].map(e => ({
  name: e.display, class: e.class, atc: e.atc, ta: e.ta,
  originalIndication: e.originalIndication || [...e.indications.values()][0]?.indication || "—",
  _canon: canon(e.display),
  indications: [...e.indications.values()],
}));

// ── 40-company roster ──
const A = ALL_TA;
const ROSTER = [
  { id: "pharmascience", name: "Pharmascience", hq: "Montréal, QC", focus: A, density: 0.45 },
  { id: "apotex", name: "Apotex", hq: "Toronto, ON", focus: A, density: 0.45 },
  { id: "teva", name: "Teva Pharmaceutical", hq: "Tel Aviv, IL", focus: A, density: 0.5 },
  { id: "sandoz", name: "Sandoz (Novartis)", hq: "Basel, CH", focus: A, density: 0.45 },
  { id: "sun", name: "Sun Pharma", hq: "Mumbai, IN", focus: A, density: 0.45 },
  { id: "mylan", name: "Viatris (Mylan)", hq: "Canonsburg, PA", focus: A, density: 0.45 },
  { id: "aurobindo", name: "Aurobindo Pharma", hq: "Hyderabad, IN", focus: A, density: 0.42 },
  { id: "drreddys", name: "Dr. Reddy's", hq: "Hyderabad, IN", focus: A, density: 0.4 },
  { id: "cipla", name: "Cipla", hq: "Mumbai, IN", focus: ["respiratory","cardiovascular","cns","inflammation","gi","metabolic","urology"], density: 0.38 },
  { id: "lupin", name: "Lupin", hq: "Mumbai, IN", focus: A, density: 0.36 },
  { id: "zydus", name: "Zydus Lifesciences", hq: "Ahmedabad, IN", focus: A, density: 0.36 },
  { id: "hikma", name: "Hikma Pharmaceuticals", hq: "London, UK", focus: ["oncology","cns","cardiovascular","gi","inflammation","hematology"], density: 0.34 },
  { id: "accord", name: "Accord Healthcare", hq: "London, UK", focus: A, density: 0.4 },
  { id: "glenmark", name: "Glenmark", hq: "Mumbai, IN", focus: ["respiratory","inflammation","cns","cardiovascular"], density: 0.3 },
  { id: "torrent", name: "Torrent Pharma", hq: "Ahmedabad, IN", focus: ["cardiovascular","cns","gi","metabolic"], density: 0.3 },
  { id: "amneal", name: "Amneal Pharmaceuticals", hq: "Bridgewater, NJ", focus: A, density: 0.34 },
  { id: "endo", name: "Endo International", hq: "Dublin, IE", focus: ["urology","cns","inflammation"], density: 0.4 },
  { id: "freseniuskabi", name: "Fresenius Kabi", hq: "Bad Homburg, DE", focus: ["oncology","hematology"], density: 0.5 },
  { id: "stada", name: "STADA Arzneimittel", hq: "Bad Vilbel, DE", focus: A, density: 0.3 },
  { id: "krka", name: "Krka", hq: "Novo Mesto, SI", focus: ["cardiovascular","cns","gi","metabolic"], density: 0.34 },
  { id: "alkem", name: "Alkem Laboratories", hq: "Mumbai, IN", focus: ["inflammation","gi","cns","cardiovascular"], density: 0.3 },
  { id: "mankind", name: "Mankind Pharma", hq: "New Delhi, IN", focus: A, density: 0.3 },
  { id: "natco", name: "Natco Pharma", hq: "Hyderabad, IN", focus: ["oncology","hematology"], density: 0.5 },
  { id: "biocon", name: "Biocon", hq: "Bengaluru, IN", focus: ["metabolic","oncology","inflammation"], density: 0.42 },
  { id: "organon", name: "Organon", hq: "Jersey City, NJ", focus: ["metabolic","cns","cardiovascular"], density: 0.38 },
  { id: "taro", name: "Taro Pharmaceutical", hq: "Haifa, IL", focus: ["inflammation","cns"], density: 0.45 },
  { id: "bausch", name: "Bausch Health", hq: "Laval, QC", focus: ["gi","inflammation","urology","cns"], density: 0.4 },
  { id: "knight", name: "Knight Therapeutics", hq: "Montréal, QC", focus: ["oncology","gi","cns","inflammation"], density: 0.32 },
  { id: "jamp", name: "Jamp Pharma", hq: "Boucherville, QC", focus: A, density: 0.28 },
  { id: "sivem", name: "Sivem Pharmaceuticals", hq: "Boucherville, QC", focus: A, density: 0.24 },
  { id: "marcan", name: "Marcan Pharmaceuticals", hq: "Ottawa, ON", focus: A, density: 0.24 },
  { id: "sanis", name: "Sanis Health", hq: "Toronto, ON", focus: A, density: 0.24 },
  { id: "strides", name: "Strides Pharma", hq: "Bengaluru, IN", focus: ["gi","cns","cardiovascular","respiratory"], density: 0.28 },
  { id: "alembic", name: "Alembic Pharmaceuticals", hq: "Vadodara, IN", focus: ["cardiovascular","cns","gi","inflammation"], density: 0.28 },
  { id: "hetero", name: "Hetero", hq: "Hyderabad, IN", focus: ["oncology","hematology","inflammation","cardiovascular"], density: 0.34 },
  { id: "lannett", name: "Lannett Company", hq: "Trevose, PA", focus: ["cns","cardiovascular","metabolic","gi"], density: 0.26 },
  { id: "nichiiko", name: "Nichi-Iko", hq: "Toyama, JP", focus: ["cardiovascular","cns","metabolic","gi"], density: 0.28 },
  { id: "towa", name: "Towa Pharmaceutical", hq: "Osaka, JP", focus: ["cardiovascular","cns","metabolic"], density: 0.28 },
  { id: "polpharma", name: "Polpharma", hq: "Starogard, PL", focus: ["cardiovascular","cns","gi","respiratory"], density: 0.28 },
  { id: "alvogen", name: "Alvogen", hq: "Pine Brook, NJ", focus: A, density: 0.28 },
];
const MAX_HOLDERS = 9;

// ── Assign molecules → companies ──
const portfolios = Object.fromEntries(ROSTER.map(c => [c.id, []]));
for (const mol of molecules) {
  const eligible = ROSTER.filter(c => c.focus.includes(mol.ta));
  let holders = eligible.filter(c => rng() < c.density);
  if (mol._canon && PS_FORCE.has(mol._canon) && !holders.find(c => c.id === "pharmascience")) {
    const ps = ROSTER.find(c => c.id === "pharmascience"); if (ps) holders.push(ps);
  }
  if (holders.length === 0) holders = [eligible[Math.floor(rng() * eligible.length)] || ROSTER[0]];
  if (holders.length > MAX_HOLDERS) holders = holders.slice(0, MAX_HOLDERS);
  const rec = { name: mol.name, class: mol.class, originalIndication: mol.originalIndication, atc: mol.atc, ta: mol.ta };
  for (const c of holders) portfolios[c.id].push(rec);
}

// ── Serialize ──
const COMPANIES_OUT = ROSTER
  .map(c => ({ id: c.id, name: c.name, hq: c.hq, molecules: portfolios[c.id] }))
  .filter(c => c.molecules.length > 0);

const POOLS_OUT = {};
for (const mol of molecules) POOLS_OUT[mol.name] = mol.indications;

const J = (x) => JSON.stringify(x, null, 2);
for (const f of ["companies.js", "indications.js", "pipeline.js"]) fs.copyFileSync(path.join(DATA, f), path.join(DATA, f + ".bak"));

fs.writeFileSync(path.join(DATA, "companies.js"),
`// ═══ COMPANY PORTFOLIO DATA (generated — mega-universe) ═══
// ${COMPANIES_OUT.length} companies. Pharmascience leads. Molecules assigned with
// realistic overlap; regenerate: node scripts/build-universe.mjs <workflow-output>
export const COMPANIES = ${J(COMPANIES_OUT)};

export const COMPANY_BY_ID = Object.fromEntries(COMPANIES.map(c => [c.id, c]));
`);

fs.writeFileSync(path.join(DATA, "indications.js"),
`// ═══ INDICATION DATA POOLS (generated — mega-universe, salt-normalized) ═══
const INDICATION_POOLS = ${J(POOLS_OUT)};

const FALLBACK = (molecule) => [
  { indication: molecule.originalIndication, countries: ["CA","US","EU","UK","JP","AU","KR","CN","IN","BR","CH","IL"], evidence: "Phase IV", patients: "N/A" },
];

export function generateIndicationData(molecule) {
  return INDICATION_POOLS[molecule.name] || FALLBACK(molecule);
}
`);

fs.writeFileSync(path.join(DATA, "pipeline.js"),
`// ═══ COMPETITIVE PIPELINE + UNMET NEED (generated — mega-universe) ═══
export const COMPETITIVE_PIPELINE = ${J(competitive)};

export const UNMET_NEED = ${J(unmet)};
`);

// ── Report ──
const totalInst = COMPANIES_OUT.reduce((s, c) => s + c.molecules.length, 0);
const totalInd = Object.values(POOLS_OUT).reduce((s, a) => s + a.length, 0);
console.log("── BUILD COMPLETE ──");
console.log(`  unique molecules: ${molecules.length}`);
console.log(`  companies: ${COMPANIES_OUT.length}`);
console.log(`  company-molecule instances: ${totalInst} (avg ${(totalInst / molecules.length).toFixed(1)} holders/molecule)`);
console.log(`  indication rows: ${totalInd}`);
console.log(`  competitive: ${Object.keys(competitive).length} | unmet: ${Object.keys(unmet).length}`);
console.log("  top portfolios:");
COMPANIES_OUT.slice().sort((a, b) => b.molecules.length - a.molecules.length).slice(0, 6).forEach(c => console.log(`    ${c.name.padEnd(26)} ${c.molecules.length}`));
